-- 1) نسخة احتياطية من صفوف post-v2 قبل الإضافة
create table if not exists leaders.questions_backup_20261101_post_v2 as
  select q.* from leaders.questions q
  where q.instrument_id in (select id from leaders.instruments where key = 'post-v2');
alter table leaders.questions_backup_20261101_post_v2 enable row level security;
comment on table leaders.questions_backup_20261101_post_v2 is 'نسخة من leaders.questions (post-v2) قبل إضافة فقرات المستوى والتوائم — للرجوع فقط';

-- 2) الفقرات الجديدة
