  ('67a22b93-0a9c-51da-92b0-620204e98c72', 'leadership', 'L-K11', 'knowledge', 'في أداة DIRECT، لماذا يأتي التعاطف بعد الحل في ترتيب الخطوات؟', '[{"label":"لأنه لحظة تثبيت الحل مع المتأثرين به","score":4},{"label":"لأن التعاطف لا يلزم قبل اختيار الحل","score":0},{"label":"لأن الحل يُعرض على الراعي قبل الفريق","score":0},{"label":"لأن التواصل يغني عنه في بداية المسار","score":0}]', 220, 'أداة DIRECT', 'ch6', 'A', null, 'advanced'),
